IFL_DATA.register("concepts", [{"id":"riba","name":"Riba","group":"Prohibitions","tags":["riba","riba-nasiah","riba-fadl"],"oneLine":"Any stipulated increase over the principal of a loan or debt, or excess/delay in exchanging like Ribawi goods, without counter-value.","points":["Riba al-Nasiah (loans/debts, delay) and Riba al-Fadl (excess in hand-to-hand exchange of the same genus).","Rate, purpose (consumption/production) and debtor's wealth are irrelevant.","Modern bank interest falls under Riba al-Nasiah."],"distinction":"Profit in sale is a return on goods with risk; Riba is a return on money/debt without risk.","trigger":"Any question on ‘Is bank interest Riba?’, loans with benefit, indexation or late-payment increases.","topicIds":["t3.2.1","t3.2.1.d","t3.2.1.e","t7.3","t17.3.1"],"origin":["f1","f2"],"aliases":[],"stage":"prohibitions","chapter":3,"altNames":["Riba (Interest)"]},{"id":"gharar","name":"Gharar","group":"Prohibitions","tags":["gharar","jahl","khatar"],"oneLine":"Excessive uncertainty about essential elements of a contract — subject matter, price, delivery — that exposes one party to undue loss.","points":["Examples: selling fish in water, a bird in the air, unborn animals, undeliverable goods.","Minor, unavoidable uncertainty is tolerated.","Invalidates commutative (exchange) contracts."],"distinction":"Gharar is uncertainty in the contract; business risk (price may rise or fall) is acceptable and necessary for profit.","trigger":"Insurance, forward sales, undefined specifications, derivatives, option-style contracts.","topicIds":["t3.2.2","t4.2.2","t6.7"],"origin":["f1","f2"],"aliases":[],"stage":"prohibitions","chapter":3,"altNames":["Gharar (Uncertainty)"]},{"id":"maisir","name":"Maisir / Qimar","group":"Prohibitions","tags":["maisir","qimar"],"oneLine":"Gambling and games of chance: gain that depends purely on chance and comes at another party's loss.","points":["Named after an ancient Arabian arrow game.","Qimar: one party gains exactly what the other loses on an uncertain event.","Conventional insurance and speculative derivatives are criticised for it."],"distinction":"Risk-taking in real business creates value; Maisir transfers wealth by chance.","trigger":"Lotteries, prize bonds, speculative derivatives, conventional insurance.","topicIds":["t3.2.3","t4.2.3","t16.2.1"],"origin":["f1","f2"],"aliases":["maisir-qimar"],"stage":"prohibitions","chapter":3,"altNames":["Maisir/Qimar (Gambling)"]},{"id":"bai","name":"Bai‘ (Sale)","group":"Sale-based modes","tags":["bai","credit-sale","trust-sales"],"oneLine":"Exchange of a thing of value for another by mutual consent — the principal lawful alternative to Riba.","points":["Seller must own and possess (actually or constructively) what he sells.","Price and object must be known; one price fixed at contract.","Credit price may exceed cash price."],"distinction":"Sale transfers ownership and risk of goods; a loan transfers money to be returned.","trigger":"‘Allah has permitted trade and forbidden Riba’ (2:275); validity of Murabaha and credit sales.","topicIds":["t6.2","t6.3.1","t6.5","t6.5.3"],"origin":["f1","f2"],"aliases":["bai-exchange"],"stage":"contracts","chapter":6,"altNames":["Bai' (Exchange of Values)"]},{"id":"murabaha","name":"Murabaha / MPO","group":"Sale-based modes","tags":["murabaha","mpo","rollover","musawamah"],"oneLine":"Sale at disclosed cost plus agreed profit; banks use Murabaha to Purchase Orderer with the client's promise to buy.","points":["Bank must own and bear the risk of the goods before selling.","Price fixed once; no increase on late payment (penalty to charity).","No rollover or buy-back."],"distinction":"Murabaha discloses cost; Musawamah bargains on price without disclosing cost.","trigger":"Working capital and trade finance; controls against back-door interest.","topicIds":["t9.3","t9.6","t9.8","t9.8.3","t9.9.1","t9.10","t14.3.4"],"origin":["f1","f2"],"aliases":[],"stage":"modes","chapter":9,"altNames":["Murabaha"]},{"id":"salam","name":"Salam","group":"Sale-based modes","tags":["salam","parallel-salam"],"oneLine":"Forward sale with full price paid in advance for precisely specified fungible goods delivered on a fixed date.","points":["Exception to ‘sell what you own’, allowed by the Prophet (pbuh).","Not for gold, silver or currencies against each other.","Parallel Salam must be independent of the first contract."],"distinction":"Salam: full prepayment, fungible goods. Istisna‘a: manufactured goods, flexible payment.","trigger":"Agricultural and working capital finance; Salam Sukuk tradability.","topicIds":["t10.2","t10.4.1","t10.4.2","t10.6","t10.10"],"origin":["f1","f2"],"aliases":[],"stage":"modes","chapter":10},{"id":"istisna","name":"Istisna‘a","group":"Sale-based modes","tags":["istisna","parallel-istisna"],"oneLine":"Order to manufacture or construct an asset to specification, with advance, deferred or instalment payment.","points":["Price and specifications must be fixed.","Parallel Istisna‘a lets banks subcontract construction.","Shart-e-Jazai: price reduction for delay benefits the buyer."],"distinction":"Istisna‘a need not be prepaid; Salam must be.","trigger":"Project, house and infrastructure finance.","topicIds":["t10.11","t10.11.3","t10.11.4","t10.11.7","t10.11.10"],"origin":["f1","f2"],"aliases":["istisnaa"],"stage":"modes","chapter":10,"altNames":["Istisna'a"]},{"id":"ijarah","name":"Ijarah","group":"Lease-based modes","tags":["ijarah","conventional-leasing"],"oneLine":"Sale of a known usufruct of a non-consumable asset for a set period against agreed rent; ownership and its risk remain with the lessor.","points":["Rent due only once the usable asset is delivered.","Lessor bears ownership costs and loss without lessee fault.","Floating rent allowed for future periods with the first fixed."],"distinction":"Ijarah transfers usufruct; sale transfers ownership. Money cannot be leased.","trigger":"Auto/house leasing, sovereign Sukuk, rent benchmarks.","topicIds":["t11.1","t11.2","t11.3","t11.3.2","t11.3.5","t11.4.4"],"origin":["f1","f2"],"aliases":[],"stage":"modes","chapter":11},{"id":"imbt","name":"Ijarah Muntahia-bi-Tamleek","group":"Lease-based modes","tags":["imbt"],"oneLine":"Lease ending in transfer of ownership through a separate unilateral promise to sell or gift.","points":["Lease and sale/gift are separate contracts.","Sale and lease-back: exceptional, sale first, about one-year gap.","AAOIFI 8/8 refund if transfer becomes impossible without lessee fault."],"distinction":"Unlike hire-purchase, rent accrues only from delivery and the bank bears ownership risk.","trigger":"Comparisons with conventional finance leases.","topicIds":["t11.5","t11.5.1","t11.4.5"],"origin":["f1","f2"],"aliases":["ijarah-muntahia-bi-tamleek"],"stage":"modes","chapter":11},{"id":"shirkah","name":"Shirkah","group":"Partnership modes","tags":["shirkah","shirkatulmilk","shirkatulaqd","shirkah-al-inan","pls","risk-sharing"],"oneLine":"Partnership combining capital, labour or creditworthiness to share profit as agreed and loss by ownership.","points":["Shirkatulmilk (ownership) vs Shirkatul‘aqd (contract).","‘Inan and Mudarabah are accepted by all jurists.","Profit by agreement, loss by capital."],"distinction":"Partners bear business risk; creditors do not.","trigger":"PLS modes, ‘most preferable’ modes, joint stock companies.","topicIds":["t12.2","t12.2.1","t12.2.2","t12.3.4"],"origin":["f1"],"aliases":[]},{"id":"musharakah","name":"Musharakah","group":"Partnership modes","tags":["musharakah","running-musharakah"],"oneLine":"All partners contribute capital and may manage; profit shared by agreed ratio, loss strictly by capital ratio.","points":["No guarantee of capital or profit by a co-partner.","Security only against negligence or misconduct.","Buy-out at market value, not at face value."],"distinction":"Musharakah: all contribute capital. Mudarabah: capital from one side only.","trigger":"Profit and loss sharing calculations; running Musharakah.","topicIds":["t12.3","t12.3.2","t12.3.4","t12.3.5","t12.7.2"],"origin":["f1","f2"],"aliases":[],"stage":"modes","chapter":12},{"id":"mudarabah","name":"Mudarabah","group":"Partnership modes","tags":["mudarabah","two-tier-mudarabah","deposit-pool"],"oneLine":"Capital from the Rabbul-mal, management by the Mudarib; profit shared as agreed, financial loss borne by the capital owner.","points":["Debt cannot be Mudarabah capital.","Mudarib is a trustee, liable only for negligence or breach.","Basis of Islamic bank deposit pools."],"distinction":"Mudarib earns a profit share, not a fee (unlike Wakalatul Istismar).","trigger":"Deposit side of Islamic banks; Mudarabah Sukuk; Takaful models.","topicIds":["t12.4","t12.4.1","t12.4.4","t12.5","t12.7.1","t8.5.2"],"origin":["f1","f2"],"aliases":[],"stage":"modes","chapter":12},{"id":"diminishing-musharakah","name":"Diminishing Musharakah","group":"Partnership modes","tags":["diminishing-musharakah","musha"],"oneLine":"Joint ownership in which the financier's units are progressively bought by the client, often with rent on the financier's share.","points":["Partnership, lease and sale are separate contracts.","Pre-agreed unit price allowed only in Shirkatulmilk.","Rent falls as units are purchased."],"distinction":"In trade (Shirkatul‘aqd) DM units must be sold at market value.","trigger":"Housing finance; Box 12.5 schedule.","topicIds":["t12.8","t12.9","t12.9.2"],"origin":["f1","f2"],"aliases":[],"stage":"modes","chapter":12},{"id":"wakalah","name":"Wakalah","group":"Accessory contracts","tags":["wakalah","fund-management"],"oneLine":"Agency: the agent acts for the principal as a trustee, with or without fee; ownership passes directly to the principal.","points":["Used in Murabaha, Salam, Istisna‘a, Ijarah and fund management.","Agent cannot delegate without consent or self-deal without disclosure.","Wakalatul Istismar: fixed fee regardless of results."],"distinction":"Wakil earns a fee; Mudarib earns a profit share.","trigger":"Agency in MPO; Takaful Wakalah model.","topicIds":["t13.2","t13.2.2","t9.8.3"],"origin":["f1","f2"],"aliases":[],"stage":"modes","chapter":13,"altNames":["Wakalah (Agency)"]},{"id":"tawarruq","name":"Tawarruq","group":"Accessory contracts","tags":["tawarruq"],"oneLine":"Buying a commodity on credit and selling it at spot to a third party to obtain cash.","points":["Differs from ‘Inah: sale to a third party, not the original seller.","Invalid if the client acts as bank's agent to buy and sell to himself.","Scholars advise limiting it to unavoidable corporate liquidity needs."],"distinction":"Tawarruq: third-party sale (preferred view permits). ‘Inah: buy-back (prohibited).","trigger":"Commodity Murabaha, personal finance, credit cards.","topicIds":["t13.3","t13.3.1","t6.11"],"origin":["f1","f2"],"aliases":[],"stage":"modes","chapter":13},{"id":"inah","name":"Bai‘ al ‘Inah","group":"Prohibitions","tags":["inah","hiyal"],"oneLine":"Sale and buy-back at different prices, producing a loan with interest — a legal ruse rejected by the majority.","points":["Used in some Malaysian Sukuk and cards.","OIC Fiqh Council and majority reject it.","Scholars impose time gaps in sale and lease-back to avoid it."],"distinction":"Sale and lease-back is allowed if the sale is complete and repurchase is delayed.","trigger":"Critiques of Sukuk, credit cards, Murabaha buy-back.","topicIds":["t6.11","t9.9.1","t15.3.4"],"origin":["f1"],"aliases":[]},{"id":"jualah","name":"Ju‘alah","group":"Accessory contracts","tags":["jualah","juala"],"oneLine":"A known reward promised to whoever achieves a specified result; nothing is due without the result.","points":["Suits uncertain work (debt recovery, finding lost property).","Offeror revoking after work starts owes a reasonable wage.","Parallel Ju‘alah allowed if independent."],"distinction":"Ju‘l is result-based; Ujrah is time-based.","trigger":"Debt collection, brokerage, feasibility services.","topicIds":["t13.4","t13.4.1","t13.4.5"],"origin":["f1","f2"],"aliases":["juaalah"],"stage":"modes","chapter":13,"altNames":["Ju'alah"]},{"id":"wad","name":"Wa‘d (Promise)","group":"Principles","tags":["wad","promise","hamish-jiddiyah"],"oneLine":"A unilateral promise, binding in commercial dealings by contemporary consensus; breach makes the promisor liable for actual loss.","points":["Bilateral binding promises are treated like contracts and restricted.","Hamish Jiddiyah secures the promise.","Used in MPO, IMBT, DM and FX cover."],"distinction":"A promise is not a contract; the sale must be executed separately.","trigger":"Binding promise to purchase; forward FX cover.","topicIds":["t5.6","t5.6.1","t9.8.2"],"origin":["f1","f2"],"aliases":["wadah-promise"],"stage":"contracts","chapter":5,"altNames":["Wa'dah (Promise)"]},{"id":"qard","name":"Qard / Qard al Hasan","group":"Principles","tags":["qard","qard-hasan","qard-al-hasan","salaf","dayn","ariyah"],"oneLine":"A loan repayable in the same kind and amount; any stipulated benefit is Riba, so every loan must be benevolent.","points":["Loans are non-commutative, virtuous acts.","Voluntary extra at repayment (Husnal Qadha) is fine if not stipulated or systematised.","Current accounts are loans to the bank."],"distinction":"Qard: fungible, returned in kind. ‘Ariyah: the same item returned.","trigger":"Current accounts, microfinance, rebates and prepayment.","topicIds":["t7.2","t7.5","t7.7","t7.11"],"origin":["f1","f2"],"aliases":["qard-hasan"],"stage":"contracts","chapter":7,"altNames":["Qard Hasan (Benevolent Loan)"]},{"id":"time-value","name":"Time value of money","group":"Principles","tags":["time-value"],"oneLine":"Recognised in pricing goods and usufruct in genuine exchange, but not as a return on loans or debts.","points":["Credit price may exceed cash price if fixed at contract.","Salam price is below spot price.","Nothing may be added once a debt exists."],"distinction":"Mark-up in trade ≠ interest on debt.","trigger":"‘Islamic banks charge interest by another name’ critiques.","topicIds":["t4.6","t6.5.3","t7.8","t17.3.4"],"origin":["f1"],"aliases":[]},{"id":"kharaj-daman","name":"Al-Kharaj bil Daman / Al-Ghunm bil Ghurm","group":"Principles","tags":["kharaj-daman","daman"],"oneLine":"Gain goes with liability for loss: profit is legitimate only for one who bears risk or responsibility.","points":["Basis of profit sharing in Shirkah.","Explains why lenders cannot earn and lessors can.","Underlies ‘no guarantee of capital’ in partnerships."],"distinction":"Rent is earned because the lessor keeps ownership risk; interest has no such risk.","trigger":"Justifying Islamic returns vs interest.","topicIds":["t4.2.6","t5.5.7"],"origin":["f1"],"aliases":[]},{"id":"bai-sarf","name":"Bai‘ al-Sarf (currency exchange)","group":"Principles","tags":["bai-sarf","forex"],"oneLine":"Exchange of monetary units must be spot, and equal in amount if of the same kind.","points":["Forward FX sale is not allowed; unilateral promise for genuine needs is.","Constructive possession includes account credits.","Spot FX may settle within two days at the deal rate."],"distinction":"Currencies are Ribawi; goods are not.","trigger":"Forex dealings, forward cover, currency settlement of debts.","topicIds":["t3.2.1.d","t4.7.2","t8.8.7","t14.4.5"],"origin":["f1"],"aliases":[]},{"id":"bai-dayn","name":"Bai‘ al Dayn (sale of debt)","group":"Prohibitions","tags":["bai-dayn","bai-al-dayn","hawalah"],"oneLine":"Sale of debt at other than face value is Riba according to the majority; debts may be assigned at par (Hawalah).","points":["Shafi‘is allowed debt sale only at par.","OIC Fiqh Council unanimously prohibits discounted debt sale.","Debt-based Sukuk trade only at face value."],"distinction":"Hawalah is assignment with recourse at par; sale is without recourse.","trigger":"Bill discounting, Murabaha receivables, Sukuk trading.","topicIds":["t6.10","t7.14","t7.16","t15.3.4"],"origin":["f1","f2"],"aliases":["bai-al-dayn"],"stage":"prohibitions","chapter":7,"altNames":["Bai' al Dayn (Sale of Debt)"]},{"id":"late-payment-penalty","name":"Penalty on default","group":"Principles","tags":["late-payment-penalty","penalty","default"],"oneLine":"Defaulters may be made to pay a charity undertaking; the bank cannot take it as income or increase the debt.","points":["Distinguish wilful defaulters from genuine hardship.","Qard: give more time; Dayn: penalty for negligent delay.","OIC Fiqh Council: void if failure was beyond control or caused no loss."],"distinction":"Penalty to charity ≠ interest to bank.","trigger":"Default management; criticism of penalties.","topicIds":["t7.13","t9.9.4","t17.4.4"],"origin":["f1"],"aliases":[]},{"id":"sukuk","name":"Sukuk","group":"Banking & markets","tags":["sukuk","ijarah-sukuk","securitization","spv","tradability","mixed-portfolio"],"oneLine":"Certificates of equal value representing undivided ownership of tangible assets, usufruct, services or project assets.","points":["Ownership Sukuk trade at market price; debt Sukuk only at par.","Returns: variable (Shirkah) or quasi-fixed (Ijarah).","Issuer may not guarantee capital or fixed profit."],"distinction":"Sukuk ≠ bonds (ownership, not debt) ≠ shares (specified assets, fixed term).","trigger":"Capital markets, sovereign finance, liquidity management.","topicIds":["t15.3","t15.3.4","t15.3.5.b","t15.3.6","t15.3.7","t11.5.3"],"origin":["f1","f2"],"aliases":[],"stage":"markets","chapter":15},{"id":"takaful","name":"Takaful","group":"Takaful & social","tags":["takaful","tabarru","waqf","family-takaful","retakaful","aqilah","insurance"],"oneLine":"Cooperative cover in which participants donate to a fund that compensates members' defined losses; surplus belongs to participants.","points":["Replaces insurance's Riba, Gharar and Maisir with Tabarru‘.","Models: Wakalah, Mudarabah, Waqf/Wakalah–Waqf (preferred).","Operator should not be a risk-taker."],"distinction":"Insurer owns underwriting surplus; Takaful participants do.","trigger":"Insurance prohibition; Takaful models; Ijarah Takaful costs.","topicIds":["t16.2.1","t16.3","t16.4","t16.4.1","t16.5"],"origin":["f1","f2"],"aliases":[],"stage":"markets","chapter":16},{"id":"islamic-banking","name":"Islamic banking","group":"Banking & markets","tags":["islamic-banking","intermediation","banking","mode-preference","mode-selection","universal-banking"],"oneLine":"Financial intermediation through trade, leasing and partnership, dealing in goods rather than money, under Shari’ah governance.","points":["Deposits: current (Qard), savings/investment (Mudarabah), Wakalah.","Assets: Murabaha, Ijarah, Salam, Istisna‘a, Musharakah, DM.","Faces additional asset, market and Shari’ah risks."],"distinction":"Not merely ‘interest-free’: a business model based on real assets and risk.","trigger":"Structure of Islamic banks, deposit pools, theory vs practice.","topicIds":["t4.1","t8.5","t8.5.1","t8.5.2","t8.6","t14.3.2"],"origin":["f1","f2"],"aliases":["islamic-banking-overview"],"stage":"markets","chapter":8,"altNames":["Islamic Banking Structure"]},{"id":"shariah-governance","name":"Shari’ah governance","group":"Banking & markets","tags":["shariah-governance","shariah-audit","standard-setters","standardisation"],"oneLine":"Shari’ah boards, internal controls and audits that ensure products and operations comply with Shari’ah.","points":["AAOIFI: board of at least three scholars; binding Fatwas.","Controls for Murabaha, Ijarah, DM and investments.","SBP framework: central board, bank advisors, annual Shari’ah audit."],"distinction":"Approving a product is not enough — boards must supervise implementation.","trigger":"Internal controls, credibility, regulatory frameworks.","topicIds":["t14.3.4","t14.appx","t18.3.2.c"],"origin":["f1"],"aliases":[]},{"id":"islamic-economics","name":"Islamic economics","group":"Foundations","tags":["islamic-economics","maqasid","distributive-justice","falah","ownership","zakat","hisbah"],"oneLine":"The study of economic behaviour guided by Shari’ah objectives — justice, welfare (Falah) and trusteeship of resources.","points":["Resources belong to Allah; humans are trustees.","Maqasid: protect faith, life, intellect, progeny, wealth.","Restrained freedom with state role (Hisbah)."],"distinction":"Differs from neoclassical economics in its value framework and distributive goals.","trigger":"Philosophy questions; why Islamic finance matters.","topicIds":["t2.2.2","t2.4.1","t2.5","t2.5.1","t2.5.2","t1.8"],"origin":["f1","f2"],"aliases":["islamic-economic-system"],"stage":"foundations","chapter":2,"altNames":["Islamic Economic System"]},{"id":"khiyar","name":"Khiyar (options)","group":"Principles","tags":["khiyar"],"oneLine":"Rights to annul a contract: of session, stipulation, defect, inspection, description, overpricing and payment.","points":["Khiyar al-Majlis until the parties separate.","Khiyar al-Shart for an agreed period.","Khiyar al-‘Aib for defects."],"distinction":"Options protect consent; they are not conventional financial options.","trigger":"Sale contract validity; Murabaha options.","topicIds":["t6.12","t9.9.2"],"origin":["f1","f2"],"aliases":["khiyar-options"],"stage":"contracts","chapter":6,"altNames":["Khiyar (Options in Sales)"]},{"id":"aqd","name":"‘Aqd (contract) and validity","group":"Principles","tags":["aqd","contract-validity","commutative-contracts","two-contracts","general-permissibility"],"oneLine":"A contract requires offer and acceptance, competent parties and a lawful, known, deliverable subject matter; contracts may be valid, voidable or void.","points":["Valid (Sahih), voidable (Fasid), void (Batil).","Two mutually contingent contracts in one are prohibited.","Everything is permissible unless prohibited (Ibahatul Asliyah)."],"distinction":"Commutative contracts may earn returns; non-commutative (loan, gift, guarantee) may not.","trigger":"Structuring products with several contracts.","topicIds":["t5.3","t5.4","t5.5","t5.5.5","t5.7","t5.8"],"origin":["f1","f2"],"aliases":["contract-elements"],"stage":"contracts","chapter":5,"altNames":["Elements of a Contract"]},{"id":"debt-equity","name":"Debt vs equity finance","group":"Foundations","tags":["debt","risk-sharing","asset-backing","fixed-return"],"oneLine":"Islamic finance allows debt through sale and lease but prefers risk-sharing equity; debt must never grow once created.","points":["Debt-creating modes: Murabaha, Salam, Istisna‘a, Ijarah.","Participatory modes: Musharakah, Mudarabah.","Preference is not the same as permissibility."],"distinction":"Conventional debt earns interest; Islamic debt arises from real sales with a fixed price.","trigger":"‘Murabaha syndrome’ and theory–practice debate.","topicIds":["t4.3","t1.2","t17.3.7","t17.4.1"],"origin":["f1"],"aliases":[]},{"id":"money","name":"Money and monetary policy","group":"Foundations","tags":["money","money-creation","monetary-policy","fictitious-assets","indexation","inflation","reserve-currency"],"oneLine":"Money is a medium of exchange and measure of value, not a commodity to rent; its creation should match real-sector growth.","points":["Paper money is treated like gold/silver for Riba rules.","No indexation of loans for inflation.","Author: fictitious money creation drives injustice."],"distinction":"Money cannot be leased because it is consumed in use.","trigger":"Inflation, indexation and policy agenda questions.","topicIds":["t4.7","t4.7.1","t4.7.3","t7.17","t17.3.3","t18.2"],"origin":["f1"],"aliases":[]},{"id":"benchmark","name":"Benchmarks (LIBOR/KIBOR)","group":"Banking & markets","tags":["benchmark"],"oneLine":"Interest-rate benchmarks may be used only as a pricing tool for goods and usufruct; Islamic benchmarks remain a future agenda.","points":["First-period Ijarah rent fixed; later periods benchmarked with cap and floor.","Use does not make the contract interest-based.","Real benchmarks need sovereign Islamic instruments."],"distinction":"Benchmark is a reference, not the contract's subject.","trigger":"‘No difference from conventional banking’ criticism.","topicIds":["t4.2.5","t11.3.2","t17.4.3","t18.3.3"],"origin":["f1"],"aliases":[]},{"id":"liquidity","name":"Liquidity management","group":"Banking & markets","tags":["liquidity","interbank"],"oneLine":"Managing surplus and shortage without interest: interbank Mudarabah, Sukuk trading, asset pools, Parallel Salam, and (as last resort) Tawarruq.","points":["Sukuk sold outright, not repo.","Pools with less than 50% receivables.","Proposed Islamic lender-of-last-resort facilities."],"distinction":"Commodity Murabaha is a grey area; Sukuk are preferable.","trigger":"Treasury and central bank questions.","topicIds":["t8.8.5","t14.4.4","t13.3.1","t18.3.3"],"origin":["f1"],"aliases":[]},{"id":"screening","name":"Equity screening and purification","group":"Banking & markets","tags":["screening","purification","stocks","shares","islamic-funds"],"oneLine":"Shares may be held if the business is Halal and financial ratios are within limits; impure income is given to charity.","points":["Exclude alcohol, pork, gambling, interest-based finance.","Ratios: interest income ≤5%, leverage ≤10–33%, illiquid assets ≥10–33%.","Liquid-capital shares trade only at par."],"distinction":"Purification cleanses dividends; it does not permit prohibited businesses.","trigger":"Islamic funds and stock investment.","topicIds":["t8.8.1","t8.8.2","t12.6","t14.3.4"],"origin":["f1"],"aliases":[]},{"id":"criticism","name":"Criticism and responses","group":"Foundations","tags":["criticism","credibility","islamic-windows"],"oneLine":"Common objections — ‘no real difference’, Murabaha syndrome, benchmarks, fixed returns, penalties — and the author's responses and concessions.","points":["Debt modes are permissible; PLS preferable.","Benchmarks are pricing tools.","Author concedes concerns on Sukuk fixed returns and socio-economic impact."],"distinction":"Distinguish the criticism, the author's response and open issues.","trigger":"‘Critically evaluate’ questions.","topicIds":["t17.2","t17.3.7","t17.4.1","t17.4.3","t17.4.6"],"origin":["f1"],"aliases":[]},{"id":"qabd","name":"Qabd (possession)","group":"Principles","tags":["qabd"],"oneLine":"A seller must own and possess the goods, physically or constructively, before selling them; possession means their risk and control have passed to him.","points":["Constructive (Hukmi) possession suffices: the goods are at the possessor’s risk and he can take delivery at will.","Sale before ownership is void; before that, only a promise to sell is allowed.","Short-selling and resale before possession are invalid."],"distinction":"Ownership (title) and possession (risk and control) are separate tests; Murabaha needs both before the sale to the client.","trigger":"Murabaha, MPO and resale questions; “can the bank sell goods it has ordered but not received?”","topicIds":["t5.4.2","t6.5.1","t9.2","t9.8.3"],"origin":["f1"],"aliases":[]},{"id":"arbun","name":"Hamish Jiddiyah and ‘Arbun","group":"Principles","tags":["arbun"],"oneLine":"Hamish Jiddiyah is security money taken before a sale to show seriousness; ‘Arbun is earnest money paid at execution as part of the price.","points":["Hamish Jiddiyah is held in trust: adjusted in the price, or only the actual loss is deducted if the promise is broken.","‘Arbun: the Hanbalis allow it; the OIC Fiqh Council and AAOIFI accept it with a specified time limit; AAOIFI prefers refunding the excess over actual loss.","Cost of funds is not part of actual loss."],"distinction":"Timing: Hamish Jiddiyah comes before the sale is executed; ‘Arbun at or after execution, as part of the price.","trigger":"Promise to purchase broken; downpayments in Murabaha, Istisna‘a or Ijarah; ‘Arbun-based options.","topicIds":["t5.6.1","t6.9","t10.11.3","t8.8.8"],"origin":["f1"],"aliases":[]},{"id":"security","name":"Kafalah and Rahn (security)","group":"Accessory contracts","tags":["kafalah","rihn","collateral"],"oneLine":"Kafalah is suretyship by a third party for a debt; Rahn (Rihn) is a pledge of the debtor’s asset held by the creditor in trust.","points":["A pledged asset stays the pledger’s: its gains and losses are his, and it cannot be appropriated in lieu of the debt.","On default it may be sold through the court or an irrevocable power of attorney, with any excess returned.","Guarantees are gratuitous: fees may cover expenses only, amount-based not time-based; a called guarantee recovers principal only."],"distinction":"Security protects recovery of what is owed; it never justifies taking more than the debt, and in PLS it covers only negligence or breach.","trigger":"Collateral questions; Salam security; L/G fees; “Islamic banks take collateral like conventional banks”.","topicIds":["t7.15","t10.5","t5.8","t14.6","t17.4.3"],"origin":["f1","f2"],"aliases":["kafalah","rahn"],"stage":"contracts","chapter":7,"altNames":["Kafalah (Guarantee)","Rahn (Pledge/Collateral)"]},{"id":"ijtihad","name":"Sources and Ijtihad","group":"Foundations","tags":["ijtihad","shariah"],"oneLine":"The Qur’an and Sunnah are primary sources; Ijma‘a and Qiyas are secondary, reached by Ijtihad — scholarly effort to solve new problems in their light.","points":["Juristic tools include Maslaha-e-Mursalah (general welfare) and ‘Urf (custom).","Ibahatul Asliyah: in dealings, whatever is not expressly prohibited is permissible.","Ijtihad cannot override a clear text (Nass) and must serve the Maqasid."],"distinction":"Ijtihad provides flexibility within the Shari’ah; it does not turn divine law into man-made law or license a Fatwa for every conventional product.","trigger":"Different interpretations, standardisation, indexation, “why can’t scholars just allow it?”","topicIds":["t2.2.1","t17.3.6","t18.3.2","t17.3.3"],"origin":["f1"],"aliases":[]},{"id":"mal","name":"Mal, ‘Ain and Dayn (property)","group":"Principles","tags":["mal","ain-dayn","mithli-qimi"],"oneLine":"Mal is anything of value that can be possessed and lawfully used; property is either specific (‘Ain) or an obligation (Dayn), and fungible (Mithli) or non-fungible (Qimi).","points":["Money is Thaman (price), not Mabi‘ (subject of sale).","Owning an asset includes its usufruct, but owning usufruct does not include the asset (as in Ijarah).","Mithli goods suit Salam; Qimi goods suit Istisna‘a."],"distinction":"‘Ain can be sold at any agreed price; Dayn (a debt) can be transferred only at face value.","trigger":"What may be sold, leased or used in Salam; sale of debt; intangible rights.","topicIds":["t5.2","t10.4.1","t10.11.2"],"origin":["f1","f2"],"aliases":["mal-usufruct-ownership"],"stage":"contracts","chapter":5,"altNames":["Mal, Usufruct and Ownership"]},{"id":"ib-risks","name":"Risks specific to Islamic banks","group":"Banking & markets","tags":["risk-management","risk"],"oneLine":"Beyond normal banking risks, Islamic banks face asset, market and Shari’ah non-compliance risk, and greater rate-of-return, fiduciary, legal and withdrawal risk.","points":["A Murabaha receivable cannot rise when market rates rise (rate-of-return risk).","Non-compliance sends income to charity and brings reputational and withdrawal risk.","Risks may be mitigated (promises, Parallel Salam, Takaful, security) but not shifted where the Shari’ah assigns them to the bank."],"distinction":"Risk management is allowed; transferring risk to another party without transferring the related reward is not.","trigger":"“Islamic banks take no risk”, securitisation risk analysis, Ijarah asset loss.","topicIds":["t4.2.9","t10.10.1","t11.5.2","t15.3.3","t17.4.3"],"origin":["f1"],"aliases":[]},{"id":"derivatives","name":"Derivatives","group":"Banking & markets","tags":["derivatives"],"oneLine":"Conventional derivatives rest on debts and rights rather than delivery; options give a right without obligation and have no direct Islamic equivalent.","points":["Some suggest ‘Arbun-based call options; reverse ‘Arbun puts are rejected by Al-Dharir.","Options on currencies, interest rates and indices have no place in Islamic finance.","Salam, Istisna‘a and Parallel Salam are only imperfect hedging substitutes."],"distinction":"Islamic hedging uses real contracts with delivery; speculative instruments priced on chance are Gharar and Maisir.","trigger":"Hedging, forward FX cover, “why is there no Islamic option?”","topicIds":["t8.8.8","t4.2.2","t14.4.5"],"origin":["f1"],"aliases":[]},{"id":"business-ethics","name":"Business ethics","group":"Foundations","tags":["business-ethics","najash","dharar","shufah","fair-pricing","transparency","ethics"],"oneLine":"Giving everyone their due is the cardinal principle: justice, honesty, disclosure of defects and freedom from harm (Dharar) in all dealings.","points":["Prohibited: Najash (bidding up without intent to buy), Khalabah (misleading marketing), Ghaban (defrauding on specifications or price).","Deceiving an unknowing market entrant (Mustarsal) is described as Riba.","Contracts must not harm third parties; Shuf‘ah (a partner’s pre-emptive right) is an example."],"distinction":"Legal validity is not enough; a transaction must also be fair, transparent and free of exploitation.","trigger":"Fair pricing, disclosure, market manipulation, Islamic bank codes of conduct.","topicIds":["t3.3","t3.3.1","t3.3.5","t18.3.2"],"origin":["f1","f2"],"aliases":[],"stage":"foundations","chapter":3,"altNames":["Business Ethics and Norms"]},{"id":"hawalah","name":"Hawalah (assignment of debt)","group":"Accessory contracts","tags":["hawalah"],"oneLine":"Transfer of a debt from one debtor to another, freeing the original debtor; it is gratuitous, at face value and immediate.","points":["Cheques, drafts, pay orders and bills of exchange are forms of Hawalah; Suftajah was the classical remittance form.","No remuneration for Hawalah itself; the majority hold the debt returns to the assignor if the assignee dies or goes bankrupt.","A debt can be transferred only at face value and with recourse — the basis for replacing bill discounting."],"distinction":"Hawalah is transfer with recourse at par; a sale of debt is without recourse and, at a discount, is Riba.","trigger":"Bill discounting, trading receivables or Murabaha Sukuk, remittances.","topicIds":["t7.14","t6.10","t5.8","t8.8.4","t15.2"],"origin":["f1","f2"],"aliases":[],"stage":"contracts","chapter":7},{"id":"maqasid","name":"Maqasid al-Shari’ah","group":"Foundations","tags":["maqasid"],"oneLine":"The objectives of the Shari’ah: people’s well-being in this world and the Hereafter, through protecting religion, life, progeny, property, intellect and honour.","points":["Secondary objectives start with justice and equity, then social security and peace.","Wealth is a trust (stewardship) to be accounted for; protection of property underpins the law of transactions.","A contract must conform to the Maqasid, not only to the letter of the rules."],"distinction":"Formal compliance satisfies the rules; Maqasid ask whether the outcome serves justice and welfare.","trigger":"Form versus substance, socio-economic impact of Islamic banking, Siddiqi’s call to redefine “Shari’ah-compliant”.","topicIds":["t2.2.2","t5.5","t17.4.6","t18.3.3"],"origin":["f1","f2"],"aliases":[],"stage":"foundations","chapter":2},{"id":"hiyal","name":"Hiyal (legal ruses)","group":"Prohibitions","tags":["hiyal"],"oneLine":"Legal devices that make a transaction technically permissible while defeating the purpose of the rule, such as ‘Inah to disguise an interest-bearing loan.","points":["Shafi‘is, Malikis and Hanbalis prohibit them; Hanafis allow only those compatible with the spirit of the Shari’ah.","Sadd al-Zarai‘ (Maliki): blocking the means to an illicit end.","Ibn Taymiyah judged such deals by the parties’ intention; a one-year gap in DM and sale and lease-back guards against ‘Inah."],"distinction":"A legitimate structure changes the substance (ownership, risk); a Hilah changes only the paperwork.","trigger":"Buy-backs, rollovers, paper-only Tawarruq, ‘Inah-based bonds and cards.","topicIds":["t6.11","t9.9.1","t15.3.4"],"origin":["f1"],"aliases":[]},{"id":"musawamah","name":"Musawamah (bargained sale)","group":"Sale-based modes","tags":["musawamah"],"oneLine":"An ordinary sale at a bargained price with no reference to the seller’s cost; all other sale conditions apply.","points":["Suits cases where cost cannot be stated precisely or supplier discounts are not disclosed.","Useful for large single deals — e.g. a bank buying a plane for $450m and selling it for $500m.","Used as an alternative to bill discounting in export finance (Section 14.4.2)."],"distinction":"Murabaha discloses cost and margin (a trust sale); Musawamah does not.","trigger":"Undisclosed costs, supplier discounts, export-bill alternatives.","topicIds":["t9.11","t9.11.1","t9.1","t14.4.2"],"origin":["f1","f2"],"aliases":[],"stage":"modes","chapter":9,"altNames":["Musawamah"]},{"id":"istijrar","name":"Bai‘ al Istijrar (supply contract)","group":"Accessory contracts","tags":["istijrar"],"oneLine":"A repeat-supply arrangement in which a supplier delivers goods from time to time on agreed price and payment terms; not a separate mode.","points":["The price may be fixed in advance, per consignment or after all deliveries.","Scholars relax price-fixing and payment rules for everyday trade where there is no Gharar (e.g. bread paid monthly).","If based on Murabaha or Salam, their conditions still apply — e.g. separate offer and acceptance for each Murabaha consignment."],"distinction":"Istijrar is a framework for repeated sales; each sale inside it must still be valid on its own terms.","trigger":"Master supply agreements, running Murabaha facilities.","topicIds":["t13.5"],"origin":["f1","f2"],"aliases":["bai-al-istijrar"],"stage":"modes","chapter":13,"altNames":["Bai' al Istijrar (Supply Contract)"]},{"id":"waqf","name":"Waqf (endowment)","group":"Takaful & social","tags":["waqf"],"oneLine":"Property retained for charitable purposes or specified beneficiaries; the Waqf is a separate entity whose corpus cannot be sold, and only its usufruct is assigned.","points":["Three kinds: religious, philanthropic and family Waqf.","A donor may also be among the beneficiaries, which is why the Waqf model suits Takaful.","Waqf and Zakat resources can support Islamic microfinance."],"distinction":"Sadaqah is given away outright; a Waqf keeps the corpus and dedicates its benefit.","trigger":"Takaful models, Tabarru‘, microfinance funding.","topicIds":["t16.3","t16.4.1","t18.3.1"],"origin":["f1"],"aliases":[]},{"id":"zakat","name":"Zakat","group":"Takaful & social","tags":["zakat"],"oneLine":"A religious obligation on wealth above needs, at a non-progressive rate — generally 2.5 % of net wealth, or 5 or 10 % of agricultural produce above a minimum — distributed to the needy (9:60).","points":["One of the six macro features of an Islamic economy.","A surety who has to pay a debt may receive Zakat as one of the Gharimeen.","Zakat and Waqf funds can finance needy small enterprises directly."],"distinction":"Zakat is an obligation with fixed rates and recipients; charity (Sadaqah) is voluntary.","trigger":"Distributive justice, need fulfilment, microfinance.","topicIds":["t1.8","t2.5","t7.15","t18.3.1"],"origin":["f1"],"aliases":[]},{"id":"islamic-funds","name":"Islamic funds (equity, Ijarah, commodity, Murabaha, mixed)","group":"Banking & markets","tags":["islamic-funds"],"oneLine":"Pooled investment vehicles run on Mudarabah (profit share) or agency (fee); what the fund holds decides whether its units can be traded.","points":["Usmani’s five categories: equity, Ijarah, commodity, Murabaha and mixed funds.","Equity and Ijarah fund units trade at market price; a Murabaha fund must be closed-end because its portfolio is debt.","A mixed fund’s units trade if tangible assets exceed 51 %."],"distinction":"A conventional fund may guarantee a return tied to face value; an Islamic fund pays only the profit actually earned.","trigger":"Mutual funds, asset management, unit trusts, screening, purification.","topicIds":["t8.8.1","t8.8.4","t15.3.8"],"origin":["f1","f2"],"aliases":["investment-funds"],"stage":"markets","chapter":8,"altNames":["Islamic Investment Funds"]},{"id":"money-market","name":"Islamic interbank money market","group":"Banking & markets","tags":["money-market"],"oneLine":"Short-term placements between banks on Mudarabah (e.g. Malaysia’s MII) or through trading in Shari’ah-compliant instruments.","points":["MII: overnight to 12 months; return based on the investee bank’s gross profit rate, with a negotiated ratio.","Elsewhere, interbank placements are treated like deposits and paid by weightage and daily product.","CODs, COIs and Ijarah-based instruments can also be traded for liquidity."],"distinction":"Conventional call money pays a fixed rate agreed upfront; an MII return is known only at maturity.","trigger":"Liquidity management, treasury, interbank placements.","topicIds":["t8.8.5","t14.4.4","t13.3.1"],"origin":["f1"],"aliases":[]},{"id":"shariah","name":"Islamic Shari'ah","group":"Foundations","groupDerivedFromStage":true,"tags":["shariah"],"stage":"foundations","chapter":2,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"philosophy-islamic-finance","name":"Philosophy of Islamic Finance","group":"Foundations","groupDerivedFromStage":true,"tags":["philosophy-islamic-finance"],"stage":"foundations","chapter":4,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"contract-validity-rules","name":"Rules for Validity of Contracts","group":"Principles","groupDerivedFromStage":true,"tags":["contract-validity-rules"],"stage":"contracts","chapter":5,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"contract-types","name":"Types of Contracts (Valid/Void/Voidable)","group":"Principles","groupDerivedFromStage":true,"tags":["contract-types"],"stage":"contracts","chapter":5,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"sale-contract-conditions","name":"Requirements of a Valid Sale","group":"Principles","groupDerivedFromStage":true,"tags":["sale-contract-conditions"],"stage":"contracts","chapter":6,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"loan-debt-rules","name":"Loan and Debt Rules","group":"Principles","groupDerivedFromStage":true,"tags":["loan-debt-rules"],"stage":"contracts","chapter":7,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"product-development-financing-practice","name":"Product Development & Financing Practice","group":"Banking & markets","groupDerivedFromStage":true,"tags":["product-development-financing-practice"],"stage":"markets","chapter":14,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"securitization","name":"Securitization","group":"Banking & markets","groupDerivedFromStage":true,"tags":["securitization"],"stage":"markets","chapter":15,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"spv","name":"Special Purpose Vehicle (SPV)","group":"Banking & markets","groupDerivedFromStage":true,"tags":["spv"],"stage":"markets","chapter":15,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"takaful-models","name":"Models of Takaful","group":"Banking & markets","groupDerivedFromStage":true,"tags":["takaful-models"],"stage":"markets","chapter":16,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"common-criticism","name":"Common Myths and Objections","group":"Principles","groupDerivedFromStage":true,"tags":["common-criticism"],"stage":"appraisal","chapter":17,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"conceptual-criticism-appraisal","name":"Appraisal of Conceptual Criticism","group":"Principles","groupDerivedFromStage":true,"tags":["conceptual-criticism-appraisal"],"stage":"appraisal","chapter":17,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"practice-criticism-appraisal","name":"Appraisal of Criticism on Practice","group":"Principles","groupDerivedFromStage":true,"tags":["practice-criticism-appraisal"],"stage":"appraisal","chapter":17,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"islamic-vs-conventional-banking","name":"Islamic vs Conventional Banking","group":"Principles","groupDerivedFromStage":true,"tags":["islamic-vs-conventional-banking"],"stage":"appraisal","chapter":17,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"way-forward","name":"The Way Forward","group":"Principles","groupDerivedFromStage":true,"tags":["way-forward"],"stage":"appraisal","chapter":18,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"policy-agenda","name":"Agenda for Policymakers","group":"Principles","groupDerivedFromStage":true,"tags":["policy-agenda"],"stage":"appraisal","chapter":18,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"potential-issues-challenges","name":"Potential, Issues and Challenges","group":"Principles","groupDerivedFromStage":true,"tags":["potential-issues-challenges"],"stage":"appraisal","chapter":18,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"mudarabah-sukuk","name":"Mudarabah Sukuk","group":"Banking & markets","groupDerivedFromStage":true,"tags":["mudarabah-sukuk"],"stage":"markets","chapter":15,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"musharakah-sukuk","name":"Musharakah Sukuk","group":"Banking & markets","groupDerivedFromStage":true,"tags":["musharakah-sukuk"],"stage":"markets","chapter":15,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"ijarah-sukuk","name":"Ijarah Sukuk","group":"Banking & markets","groupDerivedFromStage":true,"tags":["ijarah-sukuk"],"stage":"markets","chapter":15,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"salam-istisnaa-murabaha-sukuk","name":"Salam/Istisna'a/Murabaha Sukuk","group":"Banking & markets","groupDerivedFromStage":true,"tags":["salam-istisnaa-murabaha-sukuk"],"stage":"markets","chapter":15,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"mixed-portfolio-sukuk","name":"Mixed Portfolio Sukuk","group":"Banking & markets","groupDerivedFromStage":true,"tags":["mixed-portfolio-sukuk"],"stage":"markets","chapter":15,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"equity-fund-risk-profiles","name":"Equity Fund Risk Profiles","group":"Banking & markets","groupDerivedFromStage":true,"tags":["equity-fund-risk-profiles"],"stage":"markets","chapter":8,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"islamic-investment-banking","name":"Islamic Investment Banking","group":"Banking & markets","groupDerivedFromStage":true,"tags":["islamic-investment-banking"],"stage":"markets","chapter":8,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"nbfis","name":"NBFIs (Non-Bank Financial Institutions)","group":"Banking & markets","groupDerivedFromStage":true,"tags":["nbfis"],"stage":"markets","chapter":8,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"gdr","name":"Global Depository Receipt (GDR)","group":"Banking & markets","groupDerivedFromStage":true,"tags":["gdr"],"stage":"markets","chapter":8,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"public-sector-sukuk-financing","name":"Public Sector & Government Sukuk Financing","group":"Banking & markets","groupDerivedFromStage":true,"tags":["public-sector-sukuk-financing"],"stage":"markets","chapter":8,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"interbank-mudarabah-market","name":"Inter-bank Mudarabah Market","group":"Banking & markets","groupDerivedFromStage":true,"tags":["interbank-mudarabah-market"],"stage":"markets","chapter":8,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"treasury-functions","name":"Treasury Functions (Debt & Risk Management)","group":"Banking & markets","groupDerivedFromStage":true,"tags":["treasury-functions"],"stage":"markets","chapter":8,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"repo-reverse-repo","name":"Repo / Reverse Repo","group":"Banking & markets","groupDerivedFromStage":true,"tags":["repo-reverse-repo"],"stage":"markets","chapter":8,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true},{"id":"cdo","name":"Collateralized Debt Obligations (CDOs)","group":"Banking & markets","groupDerivedFromStage":true,"tags":["cdo"],"stage":"markets","chapter":8,"topicIds":[],"origin":["f2"],"aliases":[],"mapNodeOnly":true}]);
